/* ---------- process orbit ---------- */
const steps = [
  {n:"01", t:"Discover", d:"We dig into your brand, audience, and goals before a single pixel gets placed."},
  {n:"02", t:"Design", d:"Wireframes and visual direction, shaped around what your brand actually needs to say."},
  {n:"03", t:"Build", d:"We build it properly: fast, responsive, and wired for whatever comes next."},
  {n:"04", t:"Launch", d:"Deployed, tested, and handed over with everything documented and in your hands."},
  {n:"05", t:"Refine", d:"We track what's working after launch and keep tuning: SEO, speed, and conversion."}
];
const orbitContainer = document.querySelector('.orbit-wrap');
const nodeEl = document.getElementById('orbitNodes');
nodeEl.remove();
let orbitFormed = false;
function placeOrbitNodes(){
  document.querySelectorAll('.orbit-node').forEach(n=>n.remove());
  const wrapSize = orbitContainer.getBoundingClientRect().width;
  const radius = wrapSize * 0.5;
  steps.forEach((s,i) => {
    const angle = (i / steps.length) * 2 * Math.PI - Math.PI/2;
    const x = radius + radius * Math.cos(angle) * 0.82;
    const y = radius + radius * Math.sin(angle) * 0.82;
    const el = document.createElement('div');
    el.className = 'orbit-node';
    el.style.left = x + 'px';
    el.style.top = y + 'px';
    el.style.transform = 'translate(-50%,-50%) scale(0.4)';
    el.style.transitionDelay = (0.5 + i*0.11) + 's';
    el.innerHTML = `<div class="dot"></div><div class="num">${s.n}</div><h4>${s.t}</h4><p>${s.d}</p>`;
    orbitContainer.appendChild(el);
  });
  if(orbitFormed) formOrbit();
}
function formOrbit(){
  orbitFormed = true;
  orbitContainer.classList.add('in');
  document.querySelectorAll('.orbit-node').forEach(el=>{
    el.style.opacity = '1';
    el.style.transform = 'translate(-50%,-50%) scale(1)';
  });
}
if(window.innerWidth > 640){
  placeOrbitNodes();
  window.addEventListener('resize', placeOrbitNodes);
  const orbitIo = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{ if(e.isIntersecting){ formOrbit(); orbitIo.disconnect(); } });
  }, {threshold:0.35});
  orbitIo.observe(orbitContainer);
}

const pmList = document.getElementById('processMobileList');
pmList.innerHTML = steps.map(s => `<div class="pm-item"><div class="dot">${s.n}</div><div><h4>${s.t}</h4><p>${s.d}</p></div></div>`).join('');

